629					<h3>Interactive Counter</h3>
630					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
631					<div class="counter">
632						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
633						<output id="count" aria-live="off">0</output>
634						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
635						<button id="reset" type="button" aria-label="Reset count to zero">Reset</button>
636					</div>
637					<div class="live-region" aria-live="polite" aria-atomic="true">
638						<span id="count-message"></span>
639					</div>
640				</article>
