702		<script>
703			const themeToggle = document.getElementById('theme-toggle');
704			const htmlElement = document.documentElement;
705			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
706	
707			const themeColors = { light: '#ffffff', dark: '#121212' };
708			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
709			themeColorMetas.forEach((meta) => {
710				meta.dataset.defaultContent = meta.content;
711			});
712	
713			const updateThemeUI = () => {
714				const forced = htmlElement.dataset.theme;
715				const isDark = forced ? forced === 'dark' : prefersDark.matches;
716				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
717				themeToggle.textContent = isDark ? '☀️' : '🌙';
718				themeToggle.setAttribute('aria-label', label);
719				themeToggle.title = label;
720				themeColorMetas.forEach((meta) => {
721					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
722				});
723			};
724	
725			if (themeToggle) {
726				themeToggle.hidden = false;
727				updateThemeUI();
728	
729				themeToggle.addEventListener('click', () => {
730					const systemTheme = prefersDark.matches ? 'dark' : 'light';
731					const current = htmlElement.dataset.theme || systemTheme;
732					const next = current === 'dark' ? 'light' : 'dark';
733					// Choosing the system theme clears the override so the page follows the OS again.
734					try {
735						if (next === systemTheme) {
736							delete htmlElement.dataset.theme;
737							localStorage.removeItem('theme');
738						} else {
739							htmlElement.dataset.theme = next;
740							localStorage.setItem('theme', next);
741						}
742					} catch {}
743					updateThemeUI();
744				});
745	
746				prefersDark.addEventListener('change', () => {
747					if (!htmlElement.dataset.theme) {
748						updateThemeUI();
749					}
750				});
751			}
752	
753			const copyrightYear = document.getElementById('copyright-year');
754			if (copyrightYear) {
755				copyrightYear.textContent = String(new Date().getFullYear());
756			}
757	
758			const messages = [
759				"This update was announced to screen readers!",
760				"Dynamic content updates work with aria-live regions.",
761				"Live regions are essential for accessible web apps.",
762				"Try this with a screen reader like NVDA or JAWS!"
763			];
764			let nextMessage = 0;
765			let count = 0;
766			const announceBtn = document.getElementById('announce');
767			const liveMessage = document.getElementById('live-message');
768			const contactForm = document.getElementById('contact-form');
769			const emailInput = document.getElementById('email');
770			const messageInput = document.getElementById('message');
771			const messageCount = document.getElementById('message-count');
772			const formStatus = document.getElementById('form-status');
773			const countDisplay = document.getElementById('count');
774			const countMessage = document.getElementById('count-message');
775			const decreaseBtn = document.getElementById('decrease');
776			const increaseBtn = document.getElementById('increase');
777			const resetBtn = document.getElementById('reset');
778	
779			const updateCountDisplay = () => {
780				countDisplay.textContent = String(count);
781				countMessage.textContent = `Count is ${count}.`;
782			};
783	
784			if (countDisplay && countMessage) {
785				decreaseBtn?.addEventListener('click', () => {
786					count--;
787					updateCountDisplay();
788				});
789	
790				increaseBtn?.addEventListener('click', () => {
791					count++;
792					updateCountDisplay();
793				});
794	
795				resetBtn?.addEventListener('click', () => {
796					count = 0;
797					updateCountDisplay();
798				});
799			}
800	
801			if (announceBtn && liveMessage) {
802				announceBtn.addEventListener('click', () => {
803					liveMessage.textContent = messages[nextMessage];
804					nextMessage = (nextMessage + 1) % messages.length;
805				});
806			}
807	
808			if (contactForm) {
809				const emailError = document.getElementById('email-error');
810	
811				const updateMessageCount = () => {
812					if (messageInput && messageCount) {
813						const remaining = messageInput.maxLength - messageInput.value.length;
814						messageCount.textContent = remaining.toLocaleString();
815					}
816				};
817	
818				messageInput?.addEventListener('input', updateMessageCount);
819				// Browsers may restore field values on back/forward navigation.
820				window.addEventListener('pageshow', updateMessageCount);
821				updateMessageCount();
822	
823				const setEmailError = (message) => {
824					emailError.textContent = message;
825					if (message) {
826						emailInput.setAttribute('aria-invalid', 'true');
827						emailInput.setAttribute('aria-describedby', 'email-error email-help');
828					} else {
829						emailInput.removeAttribute('aria-invalid');
830						emailInput.setAttribute('aria-describedby', 'email-help');
831					}
832				};
833	
834				const validateEmail = () => {
835					let message = '';
836					if (emailInput.validity.valueMissing) {
837						message = 'Enter your email address.';
838					} else if (!emailInput.validity.valid) {
839						message = 'Enter an email address in the format name@example.com.';
840					}
841					setEmailError(message);
842					return !message;
843				};
844	
845				emailInput.addEventListener('blur', () => {
846					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
847						validateEmail();
848					}
849				});
850	
851				emailInput.addEventListener('input', () => {
852					if (emailInput.hasAttribute('aria-invalid')) {
853						validateEmail();
854					}
855				});
856	
857				contactForm.addEventListener('input', () => {
858					formStatus.textContent = '';
859				});
860	
861				contactForm.addEventListener('submit', async (event) => {
862					event.preventDefault();
863					const submitBtn = contactForm.querySelector('button[type="submit"]');
864					if (submitBtn.getAttribute('aria-disabled') === 'true') {
865						return;
866					}
867					formStatus.textContent = '';
868					if (!validateEmail()) {
869						emailInput.focus();
870						return;
871					}
872					const originalText = submitBtn.textContent;
873					// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
874					submitBtn.setAttribute('aria-disabled', 'true');
875					submitBtn.textContent = 'Sending…';
876					await new Promise(resolve => setTimeout(resolve, 800));
877					contactForm.reset();
878					setEmailError('');
879					updateMessageCount();
880					submitBtn.removeAttribute('aria-disabled');
881					submitBtn.textContent = originalText;
882					formStatus.textContent = "Thanks! This is a demo, so nothing was sent.";
883					emailInput.focus();
884				});
885			}
